const fs = require('fs');

function main() {
    const parts = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (parts.length >= 2) {
        console.log(parts[0].padStart(5, '0'));
        console.log(parts[1].padStart(5, ' '));
    }
}

main();
